import urllib.request, json, sys, os
from concurrent.futures import ThreadPoolExecutor
from PIL import Image

FILMS = {
    'charade':  ('196/3-charade/full/charade-movie-screencaps.com-{n}.jpg?class=thumbnail', 75*180),
    'assault':  ('197/6-assaultonprecinct/full/assaultonprecinct-movie-screencaps.com-{n}.jpg?class=thumbnail', 64*180),
}
STEP = 20

def fetch(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req, timeout=30) as r:
        return r.read()

def avg_color(data):
    im = Image.open(__import__('io').BytesIO(data)).convert('RGB')
    im = im.resize((1, 1), Image.BOX)
    return im.getpixel((0, 0))

os.makedirs('thumbs', exist_ok=True)

for key, (tpl, total) in FILMS.items():
    nums = list(range(1, total + 1, STEP))
    out_path = f'thumbs/{key}_profile.json'
    if os.path.exists(out_path):
        print(key, 'already done'); continue
    def work(n):
        url = 'https://caps2.b-cdn.net/' + tpl.format(n=n)
        try:
            return n, avg_color(fetch(url))
        except Exception as e:
            return n, None
    results = {}
    with ThreadPoolExecutor(max_workers=12) as ex:
        for n, c in ex.map(work, nums):
            results[n] = c
    prof = [(n, results[n]) for n in nums if results[n] is not None]
    json.dump(prof, open(out_path, 'w'))
    print(key, 'samples:', len(prof), 'first:', prof[0][1], 'last:', prof[-1][1])

